  (1, 'ET400', 'ET400 自动分离器', 'ET400 Auto Separator', '气枕/气泡送到手中,节省包装人员的时间。', 'Air pillow/bubble delivered to hands, save time for packers.', '分离器', '/uploads/accessory/ET400.jpg', NULL, NULL, 'publish', 20),
  (1, 'ET1003', 'ET1003 气垫输送系统', 'ET1003 Air Cushion Delivery System', '气垫输送系统，节省地面空间，将气垫输送到每个包装机，高效便捷。', 'Air bag delivery system, save ground space, deliver air bag to each packer, efficient and convenient.', '管路', '/uploads/accessory/ET1003.jpg', NULL, NULL, 'publish', 60),
  (1, 'ET1004', 'ET1004 气垫输送系统', 'ET1004 Air Bubble Delivery System', '气垫输送系统，节省地面空间，将气垫输送到每个包装机，高效便捷。', 'Air bag delivery system, save ground space, deliver air bag to each packer, efficient and convenient.', '管路', '/uploads/accessory/ET1004.jpg', NULL, NULL, 'publish', 100),
  (1, 'ET1005', 'ET1005 多风机输送系统', 'ET1005 Multi-fan conveying system', '高架料斗系统，适用于 ET1005，用于储存气垫。', 'Overhead Hopper system, applicable for ET1005 to store air bag.', '多风机', '/uploads/accessory/ET1005.jpg', NULL, NULL, 'publish', 110),
  (1, 'ET1007', 'ET1007 网兜系统', 'ET1007 Integrated transmission system', '集成式气垫输送系统，结构紧凑，高效便捷。', 'Integrated air bag delivery system, compact structure, efficient and convenient.', '网兜', '/uploads/accessory/ET1007.jpg', NULL, NULL, 'publish', 120),
  (1, 'FR8002', 'FR8002 收卷车', 'FR8002 Winder Cart', '新型活动推车，用于卷起气垫。', 'New movable cart,for rolling up the air cushion.', '收卷', '/uploads/accessory/FR8002.jpg', NULL, NULL, 'publish', 130),
  (1, 'FR8003', 'FR8003 收卷车', 'FR8003 Winder Cart', '新型活动推车，用于卷起气垫。', 'New movable cart,for rolling up the air cushion.', '收卷', '/uploads/accessory/FR8003.jpg', NULL, NULL, 'publish', 160),
  (1, 'FR8004', 'FR8004 收卷车', 'FR8004 Winder Cart', '新型活动推车，用于卷起气垫。', 'New movable cart,for rolling up the air cushion.', '收卷', '/uploads/accessory/FR8004.jpg', NULL, NULL, 'publish', 170),
  (1, 'EC2007', 'EC2007 移动网篮', 'EC2007 Movable Basket', '带料仓的移动式推车，可选配传感器功能，实现自动启动/停止功能。', 'Movable cart with bin, optional sensor function to have automatic start / stop function.', '网篮', '/uploads/accessory/EC2007.jpg', NULL, NULL, 'publish', 190),
  (1, 'EC2005', 'EC2005 工作台', 'EC2005 Support Cart', '可移动推车，灵活可靠，耗材可放在底座上。', 'Movable cart, flexible and reliable, material can be put at the base.', '推车', '/uploads/accessory/EC2005.jpg', NULL, NULL, 'publish', 200),
  (1, 'LT9002', 'LT9002 升降系统', 'LT9002 Lift System', '升降系统，节省地面空间，将气泡输送到每个工作台，高效便捷。', 'Lift system, saving floor space, conveying air bubbles to each worktable, efficient and convenient.', '升级系统', '/uploads/accessory/LT9002.jpg', NULL, NULL, 'publish', 210),
  (1, 'EC401', 'EC401 小支架', 'EC401 Small bracket', '铝型材小支架，稳定机器，同时可存放气垫。', 'Aluminum small bracket，stabilizes the machine while accommodating air cushion storage.', '支架', '/uploads/accessory/EC401.jpg', NULL, NULL, 'publish', 220),
  (1, 'EC402', 'EC402 大支架', 'EC402 big bracket', '铝型材大支架，稳定机器，同时可存放气垫。', 'Aluminum big bracket，stabilizes the machine while accommodating air cushion storage.', '支架', '/uploads/accessory/EC402.jpg', NULL, NULL, 'publish', 230);
